#!/usr/bin/env Rscript

# Generate +/-500-kb candidate gene--peak pairs for Satpathy K562 after the
# RNA/ATAC matrices have been generated by data_preprocessing.R.

suppressPackageStartupMessages({
  library(Matrix)
  library(Seurat)
  library(Signac)
  library(EnsDb.Hsapiens.v86)
})

args <- commandArgs(trailingOnly = FALSE)
script_arg <- grep("^--file=", args, value = TRUE)
script_path <- if (length(script_arg)) sub("^--file=", "", script_arg[[1]]) else "data/SatpathyK562/gene_peak_preprocessing.R"
project_root <- normalizePath(file.path(dirname(script_path), "../.."), mustWork = TRUE)
data_dir <- file.path(project_root, "data", "SatpathyK562")
source(file.path(project_root, "R", "helper.R"))

rna <- readRDS(file.path(data_dir, "SatpathyK562.rna.rds"))
atac <- readRDS(file.path(data_dir, "SatpathyK562.atac.rds"))
meta <- readRDS(file.path(data_dir, "SatpathyK562.meta.rds"))
stopifnot(identical(colnames(rna), colnames(atac)), identical(colnames(rna), rownames(meta)))

annotation <- Signac::GetGRangesFromEnsDb(EnsDb.Hsapiens.v86::EnsDb.Hsapiens.v86)
annotation_levels <- seqlevels(annotation)
seqlevels(annotation) <- ifelse(annotation_levels == "MT", "chrM", paste0("chr", annotation_levels))
object <- CreateSeuratObject(counts = rna, assay = "RNA", meta.data = meta)
object[["ATAC"]] <- CreateChromatinAssay(counts = atac, annotation = annotation)
gene_peak_df <- GetGenePeakPairs(object, annotation, distance = 500000)
if ("peak" %in% names(gene_peak_df)) {
  gene_peak_df$peak <- sub(":", "-", gene_peak_df$peak, fixed = TRUE)
}
saveRDS(gene_peak_df, file.path(data_dir, "SatpathyK562.gene_peak_df.rds"), compress = TRUE)
message("Saved ", nrow(gene_peak_df), " candidate gene-peak pairs")
